package com.example.takura.privacy.controller;
import com.example.takura.identity.domain.StaffPrincipal;import com.example.takura.privacy.application.PrivacyOperationsService;import com.example.takura.identity.controller.StaffRequestPrincipal;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/privacy") public class PrivacyOperationsController{private final PrivacyOperationsService service;public PrivacyOperationsController(PrivacyOperationsService s){service=s;}@PostMapping("/requests")ResponseEntity<?>create(@StaffRequestPrincipal StaffPrincipal p,@RequestBody Create b){return ResponseEntity.status(201).body(service.create(p,b.enquiryId(),new PrivacyOperationsService.Command(b.type(),b.identityEvidenceReference(),b.scope())));}@PostMapping("/requests/{id}/approve")Object approve(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestHeader("If-Match")long r){return service.approve(p,id,r);}@GetMapping(value="/requests/{id}/export",produces="text/csv")ResponseEntity<String>export(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=privacy-export.csv").cacheControl(CacheControl.noStore()).body(service.accessCsv(p,id));}@PostMapping("/requests/{id}/correct")Object correct(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestHeader("If-Match")long r,@RequestBody Correction b){return service.executeCorrection(p,id,r,new PrivacyOperationsService.Correction(b.fullName(),b.email(),b.phone(),b.area()));}@PostMapping("/requests/{id}/delete")Object delete(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestHeader("If-Match")long r,@RequestBody Map<String,String>b){return service.executeDeletion(p,id,r,b.getOrDefault("outcome","Authorised deletion completed"));}@PostMapping("/holds")ResponseEntity<?>hold(@StaffRequestPrincipal StaffPrincipal p,@RequestBody Hold b){return ResponseEntity.status(201).body(Map.of("id",service.placeHold(p,b.enquiryId(),b.reason())));}@PostMapping("/marketing-withdrawals")ResponseEntity<Void>withdraw(@StaffRequestPrincipal StaffPrincipal p,@RequestBody Withdrawal b){service.withdrawMarketing(p,b.enquiryId(),b.noticeVersion());return ResponseEntity.noContent().build();}public record Create(UUID enquiryId,String type,String identityEvidenceReference,String scope){}public record Correction(String fullName,String email,String phone,String area){}public record Hold(UUID enquiryId,String reason){}public record Withdrawal(UUID enquiryId,String noticeVersion){}}
